selected.compute:
options = read('/input/options')
result = []
for group in combinations(options, 2):
    ids = [group[0]['id'], group[1]['id']]
    if valid(ids):
        result = ids
        break
if len(result) == 0:
    for group in combinations(options, 3):
        ids = [group[0]['id'], group[1]['id'], group[2]['id']]
        if valid(ids):
            result = ids
            break
if len(result) == 0:
    for group in combinations(options, 4):
        ids = [group[0]['id'], group[1]['id'], group[2]['id'], group[3]['id']]
        if valid(ids):
            result = ids
            break

selected.effects:
artifact = read('/output/selection')
if artifact != None:
    if valid(artifact):
        result = artifact
    else:
        result = []
if len(result) == 0:
    status_value = status('report')
    receipt_value = receipt('report')
    if status_value == 'sent' or receipt_value == 'success':
        result = []
    else:
        raise Exception('No valid selection')
if artifact == None:
    write('/output/selection', result)
status_value = status('report')
receipt_value = receipt('report')
if receipt_value != 'success' and status_value != 'sent':
    if receipt_value == 'unknown':
        status_value = status('report')
    else:
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
